+
+/** A single native tile's pixel/coverage pair is independent. Drain both jobs
+ * before cleanup, so a late decoder can never publish into a disposed view. */
+async function preparePair<T>(first: Promise<T>, second: Promise<T>): Promise<[T, T]> {
+  const results = await Promise.allSettled([first, second]);
+  for (const result of results) if (result.status === 'rejected') throw result.reason;
+  return [(results[0] as PromiseFulfilledResult<T>).value, (results[1] as PromiseFulfilledResult<T>).value];
+}

