import os,json,hashlib,subprocess,statistics,time,urllib.request
from pathlib import Path
from PIL import Image
import numpy as np
out=Path('/tmp/canoli-wet-direct-controlled-2');assert not out.exists();out.mkdir()
stage=Path('/tmp/canoli-wet-direct-stage');baseline=Path('/tmp/canoli-wet-rail-baseline');root=Path('/home/kestrel/projects/luma-editor')
epoch=json.load(open('/tmp/canoli-wet-direct-stage-epoch-4.json'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
script=stage/'scripts/benchmark-wet-input.mjs';source=script.read_bytes();(out/'harness.mjs').write_bytes(source)
releases={'baseline':{'root':baseline,'release':{name.removeprefix('dist/'):digest for name,digest in json.load(open(baseline/'release-manifest.json')).items()},'port':5234},'candidate':{'root':stage,'release':epoch['release'],'port':5229}}
assert '1354 passed' in Path('/tmp/canoli-wet-direct-stage-unit-full-4.log').read_text()
for name,count in [('native-3',92),('production-2',82)]:
 report=json.load(open('/tmp/canoli-wet-direct-stage-'+name+'.json'));assert tuple(report['stats'][key] for key in ['expected','skipped','unexpected','flaky'])==(count,0,0,0),report['stats'];assert not report.get('errors')
def source_check():
 for name,digest in epoch['source'].items():assert sha(stage/name)==digest,('candidate',name)
 for name,digest in json.load(open(baseline/'source-manifest.json')).items():assert sha(root/name)==digest,('main',name)
 for name,digest in json.load(open(baseline/'prior-evidence.json')).items():assert sha(root/name)==digest,name
 assert script.read_bytes()==source

def verify(label):
 data=releases[label];proof={}
 for name,digest in data['release'].items():
  assert sha(data['root']/'dist'/name)==digest,(label,name)
  with urllib.request.urlopen(f"http://127.0.0.1:{data['port']}/"+name,timeout=10) as response:
   content=response.read();actual=hashlib.sha256(content).hexdigest();assert actual==digest,(label,name);proof[name]={'sha256':actual,'bytes':len(content),'status':response.status}
 return proof
source_check()
for label in releases:(out/(label+'-release.json')).write_text(json.dumps(verify(label),indent=2)+'\n')
runs=[]
for round in range(3):
 for label in (['baseline','candidate'] if round%2==0 else ['candidate','baseline']):
  destination=out/f'round-{round+1}-{label}';env={**os.environ}
  for name in ['CANOLI_WET_INPUT_PROFILE','CANOLI_WET_INPUT_DIAGNOSTIC','CANOLI_WET_INPUT_CASES']:env.pop(name,None)
  env.update(CANOLI_WET_INPUT_OUTPUT=str(destination),CANOLI_WET_INPUT_URL=f"http://127.0.0.1:{releases[label]['port']}/",PLAYWRIGHT_CHROMIUM_EXECUTABLE='/home/kestrel/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome')
  source_check();loadBefore=os.getloadavg();started=time.time()
  with (out/f'round-{round+1}-{label}.log').open('x') as log:result=subprocess.run(['node','--import','tsx',str(script)],cwd=str(stage),env=env,stdout=log,stderr=subprocess.STDOUT)
  assert result.returncode==0,(round,label,result.returncode)
  report=json.loads((destination/'report.json').read_text());assert not report['diagnostic'] and len(report['reports'])==6
  for case in report['reports']:
   assert len(case['samples'])==20 and case['controls'] and not case['profiled'] and case['oneUndoExactModelAndPixels']
   samples=sorted(row['duration'] for row in case['samples']);assert case['p95']==samples[18],(case['p95'],samples)
  images=[]
  for image in sorted(destination.glob('*.png')):
   a=np.asarray(Image.open(image).convert('RGBA'));b=np.asarray(Image.open(Path('/tmp/canoli-wet-resident-controlled-1/round-1-candidate')/image.name).convert('RGBA'))
   assert a.shape==b.shape==(128,512,4) and np.array_equal(a,b),image
   images.append({'file':image.name,'sha256':sha(image),'allNativeRgbaEqual':True})
  assert len(images)==18
  run={'round':round+1,'release':label,'started':started,'ended':time.time(),'loadBefore':loadBefore,'loadAfter':os.getloadavg(),'images':images,'report':report}
  runs.append(run);(out/'progress.json').write_text(json.dumps(runs,indent=2)+'\n')
  verify(label);source_check();print(round+1,label,'all6fixtures/120newlymatchedpoints/18exactnativePNGs verified',flush=True)
summary=[]
for fixture in [row['fixture']['id'] for row in runs[0]['report']['reports']]:
 row={'fixture':fixture}
 for label in releases:
  cases=[case for run in runs if run['release']==label for case in run['report']['reports'] if case['fixture']['id']==fixture]
  row[label]={'p95':[case['p95'] for case in cases],'medianP95':statistics.median(case['p95'] for case in cases),'maximumSample':max(case['maximum'] for case in cases),'overlappingNativeLongTasks':sum(len(case['overlappingLongTasks']) for case in cases),'maximumObservedFrameGap':max(max(case['frameGaps'],default=0) for case in cases)}
 summary.append(row)
payload={'format':'canoli-wet-controlled-comparison','version':1,'harnessSha256':hashlib.sha256(source).hexdigest(),'runs':runs,'summary':summary,'limits':['Three alternating unprofiled release pairs on one named headless Chromium host after known correctness jobs finished; external machine activity is not controlled.','Twenty paced moves per small synthetic fixture are a canvas-copy proxy, not sustained input, physical display/GPU/tablet or completeF06/F14/process-memory acceptance.','Native75mscontrols, matching pixels, source/release identity, all21points and exact undo are retained. No universal latency or60fps guarantee follows.']}
(out/'comparison.json').write_text(json.dumps(payload,indent=2)+'\n');print(json.dumps(summary,indent=2),flush=True)

